<?php

namespace Schemastud\Frame\Registry;

use InvalidArgumentException;
use Rushing\Popcorn\Registries\BasicRegistry;
use Rushing\Popcorn\Registries\ForwardsToRegistryStore;
use Rushing\Popcorn\Registries\Gated;
use Rushing\Popcorn\Registries\IsRegistry;
use Rushing\Popcorn\Registries\Key;
use Rushing\Popcorn\Registries\OnKeyDuplicate;
use Rushing\Popcorn\Registries\PopulationRequirement;
use Rushing\Popcorn\Registries\Registrant;
use Rushing\Popcorn\Registries\Registry;
use Rushing\Popcorn\Registries\RegistryKey;

/**
 * The `frame.contexts` registry, generated by `popcorn:make:registry` (frame-foundation 90; the shape is decision 86's
 * ruling): every render context frame projects, one {@see WidgetContext} per key `frame.contexts.<name>`.
 *
 * **Who registers.** Frame seeds its own seven in this constructor, as `schemastud/laravel-frame`, in today's wire
 * order. A package or host adds a context, or replaces one of frame's, from its own provider's `boot()` (never
 * `register()`, where a write can land on an instance the container later replaces):
 * `app(WidgetContextRegistry::class)->register(new WidgetContext(...))`. It is an extension point, unlike the resource
 * registry port of ADR-0008.
 *
 * **Who reads.** {@see WidgetContextProjector}, handed this registry by constructor (frame's provider binds both): the
 * block's `known` and `inherits`, and the projector's grain and class-level checks. Nothing else locates it.
 *
 * **Policy.** `Supersede`: a replacement keeps the displaced entry's slot, so `known` keeps its order, and it must keep
 * its grain. Registration refuses a name that is not one key segment, a fallback naming the entry itself, any fallback on
 * `edit`, a grain change, and `reserved` on a non-property grain. The edges (each fallback registered, of the same
 * grain) are checked once all registration is done, by {@see assertEdges()}: from frame's provider in an
 * `$app->booted()` pass, or on the projector's first read where there is no container. There is no `forget`: a context
 * is replaced, never removed.
 *
 * @implements Registry<WidgetContext>
 */
#[IsRegistry(
    root: 'frame.contexts',
    entryType: WidgetContext::class,
    onKeyDuplicate: OnKeyDuplicate::Supersede,
    populationRequirement: PopulationRequirement::Required,
    description: 'Render contexts frame projects (the block\'s known and inherits): frame\'s seven, plus any a package or host registers or supersedes in boot().',
)]
class WidgetContextRegistry implements Gated, Registry
{
    use ForwardsToRegistryStore;

    /** The registrant frame's own seven are recorded under. */
    public const FRAME = 'schemastud/laravel-frame';

    /** @var BasicRegistry<WidgetContext> */
    private BasicRegistry $entries;

    public function __construct()
    {
        $this->entries = BasicRegistry::for($this);

        // Frame's seven, in today's wire order (the block's `known`), and its two edges.
        foreach ([
            new WidgetContext('edit', ContextGrain::Property),
            new WidgetContext('detail', ContextGrain::Property),
            new WidgetContext('list-column', ContextGrain::Property, reserved: ['row-actions']),
            new WidgetContext('list-item', ContextGrain::Record),
            new WidgetContext('row-cell', ContextGrain::Property, fallback: ['edit']),
            new WidgetContext('summary', ContextGrain::Collection),
            new WidgetContext('overview', ContextGrain::Collection, fallback: ['summary']),
        ] as $context) {
            $this->register($context, by: self::FRAME);
        }
    }

    /**
     * Register a context, or supersede one already registered under its name. The first argument is the entry
     * itself (its key is `frame.contexts.<name>`); the keyed form `register($key, $context)` the {@see Registry}
     * contract names works too, and its key must be the entry's.
     *
     * @throws InvalidArgumentException on a name that is not one key segment, a fallback naming the entry itself,
     *                                  any fallback on `edit`, a supersession that changes grain, or `reserved` on a
     *                                  non-property grain
     */
    public function register(RegistryKey|string|WidgetContext $key, mixed $entry = null, ?string $by = null, ?string $ability = null): static
    {
        if ($key instanceof WidgetContext) {
            $entry = $key;
        }

        if (! $entry instanceof WidgetContext) {
            throw new InvalidArgumentException('frame.contexts takes a '.WidgetContext::class.' entry.');
        }

        $this->refuse($entry, $by ?? Registrant::current());

        $at = $this->keyFor($entry->name);
        if (! $key instanceof WidgetContext && (string) $key !== (string) $at) {
            throw new InvalidArgumentException("Render context [{$entry->name}] registers under [{$at}], not [{$key}].");
        }

        $this->entries->register($at, $entry, $by, $ability);

        return $this;
    }

    /** The context registered under a name, or null. */
    public function context(string $name): ?WidgetContext
    {
        if (preg_match(Key::SEGMENT_PATTERN, $name) !== 1) {
            return null;
        }

        $entry = $this->entries->unfiltered()->tryResolve($this->keyFor($name));

        return $entry instanceof WidgetContext ? $entry : null;
    }

    /**
     * Every registered context, in registration order (a supersession keeps its slot).
     *
     * @return list<WidgetContext>
     */
    public function all(): array
    {
        $store = $this->entries->unfiltered();

        return array_values(array_map(fn (RegistryKey $key): WidgetContext => $store->resolve($key), $store->keys()));
    }

    /**
     * The block's `known`: every context's name, in registration order.
     *
     * @return list<string>
     */
    public function known(): array
    {
        return array_map(fn (WidgetContext $context): string => $context->name, $this->all());
    }

    /**
     * The block's `inherits`: each context with a non-empty fallback, in registration order, to its fallback list.
     *
     * @return array<string, list<string>>
     */
    public function inherits(): array
    {
        $edges = [];
        foreach ($this->all() as $context) {
            if ($context->fallback !== []) {
                $edges[$context->name] = array_values($context->fallback);
            }
        }

        return $edges;
    }

    /**
     * The edges check, run once registration is over: every fallback names a registered context of the same grain.
     * Name order of registration cannot change its answer, because it reads the finished registry.
     *
     * @throws InvalidArgumentException naming the missing (or wrong-grain) context and the registered ones
     */
    public function assertEdges(): void
    {
        foreach ($this->all() as $context) {
            foreach ($context->fallback as $fallback) {
                $target = $this->context($fallback);

                if ($target === null) {
                    throw new InvalidArgumentException(
                        "Render context [{$context->name}] falls back to [{$fallback}], which is not registered; "
                        .'registered contexts: '.implode(', ', $this->known()).'.'
                    );
                }

                if ($target->grain !== $context->grain) {
                    throw new InvalidArgumentException(
                        "Render context [{$context->name}] ({$context->grain->value} grain) falls back to [{$fallback}] "
                        ."({$target->grain->value} grain); a fallback must be of the same grain. Registered contexts: "
                        .implode(', ', $this->known()).'.'
                    );
                }
            }
        }
    }

    private function refuse(WidgetContext $context, ?string $by): void
    {
        if (preg_match(Key::SEGMENT_PATTERN, $context->name) !== 1) {
            throw new InvalidArgumentException(
                "Render context name [{$context->name}] is not one registry key segment (".Key::SEGMENT_PATTERN.').'
            );
        }

        if (in_array($context->name, $context->fallback, true)) {
            throw new InvalidArgumentException("Render context [{$context->name}] cannot fall back to itself.");
        }

        if ($context->name === 'edit' && $context->fallback !== []) {
            throw new InvalidArgumentException('Render context [edit] takes no fallback: it is the form control, and other contexts fall back to it.');
        }

        if ($context->reserved !== [] && $context->grain !== ContextGrain::Property) {
            throw new InvalidArgumentException(
                "Render context [{$context->name}] is {$context->grain->value} grain; only a property-grain context reserves class-level widget names."
            );
        }

        $displaced = $this->context($context->name);
        if ($displaced !== null && $displaced->grain !== $context->grain) {
            $was = $this->entries->registrantOf($this->keyFor($context->name)) ?? 'an unnamed registrant';
            $now = $by ?? 'an unnamed registrant';

            throw new InvalidArgumentException(
                "Render context [{$context->name}] is {$displaced->grain->value} grain (registered by {$was}); "
                ."{$now} cannot supersede it with {$context->grain->value} grain."
            );
        }
    }

    private function keyFor(string $name): Key
    {
        return Key::parse('frame.contexts.'.$name);
    }

    protected function store(): BasicRegistry
    {
        return $this->entries;
    }
}
